/**
 * Inngest Function: Flywheel Feedback Dispatcher (registered).
 *
 * Applies one observed feedback event to the persisted Thompson posterior
 * exactly once, then derives the next decision from persisted data with a
 * seeded RNG. Fixture/mock metrics are refused: production learning must not
 * consume numbers that were generated by `Math.random()` in a fetcher.
 *
 * Layer: forest/inngest/functions
 * @module forest/inngest/functions/flywheel-feedback-dispatcher
 */

import { inngest } from '@/seed/inngest/client';
import { getD1 } from '@/seed/db/client';
import { recordLearning } from '@/tree/creative-memory';
import {
  chooseNextArm,
  recordFeedbackOnce,
  type FeedbackEvent,
} from '@/tree/affiliate/optimization/feedback-repository';
import {
  encodePersonaArmKey,
  type PersonaArmSpec,
} from '@/tree/affiliate/optimization/persona-arm-codec';

export interface EvaluatedFeedbackEventData {
  userId: string;
  /** Server-resolved workspace id. */
  tenantId?: string;
  /** Stable provider/job event id; used as the exactly-once key. */
  eventId?: string;
  jobId: string;
  platform: string;
  hookScore: number;
  retentionScore: number;
  netRoiUsd: number;
  conversions: number;
  revenueUsd: number;
  /** Observed impressions in the same cohort/window (required, not hardcoded). */
  impressions?: number;
  costUsd?: number;
  observedAtMs?: number;
  seed?: number;
  candidateArmIds?: string[];
  /** True for mock/fixture metrics — never persisted as real observations. */
  isFixture?: boolean;
  /**
   * 2027 Maturity guard: if commission is pending validation / hold period,
   * conversions and rewards are held until settlement. Defaults to true if omitted.
   */
  isMatured?: boolean;
  /**
   * Explicit lifecycle transition:
   * - 'initial': First observation of impressions, clicks, costs, and tentative/settled conversions.
   * - 'settlement': Subsequent maturation of previously pending conversions; pulls & costs already counted.
   * - 'reversal': Subsequent cancellation / chargeback of previously credited conversions.
   */
  lifecycleStage?: 'initial' | 'settlement' | 'reversal';
  /** Optional composite persona arm attributes for Video Gender 2027 */
  personaArm?: PersonaArmSpec;
  /** Optional armId override */
  armId?: string;
  /** Cohort / Invoice lineage identifier */
  cohortId?: string;
  /** Provider identifier */
  provider?: string;
  /** Logical adjustment identifier */
  adjustmentId?: string;
}

export interface FlywheelResult {
  processed: boolean;
  promoted: boolean;
  armId: string;
  applied?: boolean;
  nextArmId?: string | null;
  reason?: string;
}

interface InngestStepContext {
  run: <T>(name: string, fn: () => Promise<T>) => Promise<T>;
}

export async function processFlywheelFeedbackDispatcher({
  event,
  step,
}: {
  event: { data: unknown };
  step: InngestStepContext;
}): Promise<FlywheelResult> {
  const data = event.data as EvaluatedFeedbackEventData;
  const armId =
    data.armId ||
    (data.personaArm ? encodePersonaArmKey(data.personaArm) : `arm_${data.platform}_${data.jobId.slice(0, 8)}`);
  const notProcessed = (reason: string): FlywheelResult => ({ processed: false, promoted: false, armId, reason });

  if (data.isFixture === true) return notProcessed('FIXTURE_METRICS_NOT_OBSERVED');
  const tenantId = data.tenantId ?? '';
  if (!tenantId) return notProcessed('TENANT_REQUIRED');
  if (!Number.isInteger(data.impressions) || (data.impressions ?? 0) < 0) {
    return notProcessed('OBSERVED_IMPRESSIONS_REQUIRED');
  }
  const db = await getD1();
  if (!db) return notProcessed('DB_UNAVAILABLE');

  const observedAtMs = data.observedAtMs ?? Date.now();
  const eventId = data.eventId ?? `${tenantId}:${data.jobId}:${data.platform}:${observedAtMs}`;
  const impressions = data.impressions ?? 0;
  const rewardCents = Math.round(data.revenueUsd * 100);
  const costCents = Math.round((data.costUsd ?? 0) * 100);
  const seed = data.seed ?? hashSeed(eventId);
  const isReversal = data.lifecycleStage === 'reversal';
  const conversions = isReversal ? data.conversions : Math.min(data.conversions, impressions);
  const feedback: FeedbackEvent = {
    eventId,
    armId,
    impressions,
    conversions,
    rewardCents,
    costCents,
    observedAtMs,
    ...(data.isMatured !== undefined ? { isMatured: data.isMatured } : {}),
    ...(data.lifecycleStage ? { lifecycleStage: data.lifecycleStage } : {}),
    ...(data.cohortId ? { cohortId: data.cohortId } : {}),
    ...(data.provider ? { provider: data.provider } : {}),
    ...(data.adjustmentId ? { adjustmentId: data.adjustmentId } : {}),
  };

  const persisted = await step.run('update-thompson-posterior', async () =>
    recordFeedbackOnce(db, tenantId, feedback),
  );
  if (!persisted.ok) return notProcessed(persisted.error);

  const decision = await step.run('derive-next-decision', async () =>
    chooseNextArm(db, tenantId, data.candidateArmIds?.length ? data.candidateArmIds : [armId], seed),
  );

  const contributionPositive = rewardCents - costCents > 0 && data.netRoiUsd > 0;
  const isWinning = data.hookScore >= 80 && (data.retentionScore >= 75 || contributionPositive);

  const memoryResult = await step.run('evaluate-creative-memory-promotion', async () => {
    if (!isWinning || !contributionPositive || !persisted.value.applied) {
      return { promoted: false, memoryId: null as string | null };
    }
    const recorded = await recordLearning(
      data.userId,
      'creative',
      `observed_hook_${data.platform}`,
      {
        jobId: data.jobId,
        platform: data.platform,
        hookScore: data.hookScore,
        retentionScore: data.retentionScore,
        impressions,
        netRoiUsd: data.netRoiUsd,
        eventId,
      },
      `Observed telemetry: hook=${data.hookScore}, retention=${data.retentionScore}, net ROI=${data.netRoiUsd}`,
      'workspace',
      tenantId,
    );
    return { promoted: true, memoryId: recorded.id };
  });

  return {
    processed: true,
    promoted: memoryResult.promoted,
    armId,
    applied: persisted.value.applied,
    nextArmId: decision?.selectedArmId ?? null,
  };
}

function hashSeed(value: string): number {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

export const flywheelFeedbackDispatcherJob = inngest.createFunction(
  {
    id: 'flywheel-feedback-dispatcher',
    name: 'Observed Feedback → Persisted Posterior → Next Decision',
    retries: 2,
  },
  { event: 'social.analytics.feedback_evaluated' },
  processFlywheelFeedbackDispatcher,
);
